// Generated by `just generate` from `src/plugins/claudetto/slices/checks/adapters/cli.ts`. Edit the source and run `just generate`.
// The CLI `claudetto-run-checks` of the `checks` slice. The launcher `bin/claudetto-run-checks` calls `main`.
//
//   claudetto-run-checks "bun test" "bun run lint"
//
// Each argument is one command. The commands run in order, in the folder where the CLI runs.
// A command of plain words runs with no shell. A command with shell syntax (a pipe, a list, a quote, a glob, `$`) runs through `bash -o pipefail -c`, so a failed part of a pipe fails the check.
// For each command the CLI prints the exit status, the time, and the last lines of the output of a failed command.
// The exit code decides pass or fail. The CLI reads no word of the output, because the words depend on the language of the tool. The output of a passing command is printed when it is short, at most `MAX_PASS_OUTPUT_LINES` lines.
// The full output goes to a log file in `CHECKS_DIR`, and the summary names the file.
// The guard and the asks see the batch before it runs: the `guard` and `asks` slices read each argument of `claudetto-run-checks` as a command.
// A timeout ends the check and each child of it, because each check runs in a process group of its own.
// Exit status: 0 when all commands pass, 1 when any command fails, 2 for a usage error.
// An argument that starts with `-` is a flag, so the CLI exits 2 before it runs any command.

import fs from "node:fs/promises";
import path from "node:path";
import { CHECKS_DIR } from "../../../kernel/paths.ts";
import type {
  Clock,
  Env,
  ProcessOptions,
  ProcessResult,
} from "../../../kernel/ports.ts";
import { flagArg, plainArgv, shellArgv } from "../domain/command.ts";
import { failureLines } from "../domain/failures.ts";
import { passOutput } from "../domain/output.ts";
import {
  logName,
  type Outcome,
  passed,
  renderOutcome,
  renderTotal,
  type Stop,
} from "../domain/summary.ts";
import { COMMAND_TIMEOUT_MS, RUN_ID_LENGTH } from "../limits.ts";
import { FLAG_ERROR } from "../prompts.ts";

const USAGE = 'Usage: claudetto-run-checks "<command>" ["<command>" ...]';

/** Runs a program and gives its result. A fake gives the result with no wait. */
export interface CheckRunner {
  run(
    file: string,
    args: readonly string[],
    options: ProcessOptions,
  ): ProcessResult | Promise<ProcessResult>;
}

/** Ends the process group of `pid`: the check and each child that it started. */
const killGroup = (pid: number): void => {
  try {
    process.kill(-pid, "SIGKILL");
  } catch (err) {
    // The group is gone when the check ended before the kill.
    if ((err as { code?: string }).code !== "ESRCH") throw err;
  }
};

/**
 * The runner of the CLI. The check starts in a process group of its own, so that a time-out ends the check and each child of it.
 * `Bun.spawnSync` with a `timeout` ends only the first process, and the children keep the pipes open.
 */
export const groupRunner: CheckRunner = {
  run: async (file, args, options) => {
    const proc = Bun.spawn([file, ...args], {
      ...(options.cwd === undefined ? {} : { cwd: options.cwd }),
      stdout: "pipe",
      stderr: "pipe",
      detached: true,
    });
    let timedOut = false;
    const timer =
      options.timeout === undefined
        ? undefined
        : setTimeout(() => {
            timedOut = true;
            killGroup(proc.pid);
          }, options.timeout);
    const [stdout, stderr, exitCode] = await Promise.all([
      new Response(proc.stdout).text(),
      new Response(proc.stderr).text(),
      proc.exited,
    ]);
    clearTimeout(timer);
    return {
      exitCode: timedOut || proc.signalCode ? null : exitCode,
      stdout,
      stderr,
      ...(proc.signalCode ? { signal: String(proc.signalCode) } : {}),
      timedOut,
    };
  },
};

/** The ports of the CLI. A test gives fakes. */
export interface Deps {
  readonly runner: CheckRunner;
  readonly clock: Clock;
  readonly env: Env;
  readonly writeLog: (file: string, text: string) => Promise<void>;
  readonly log: (line: string) => void;
  readonly error: (line: string) => void;
}

const defaults = (): Deps => ({
  runner: groupRunner,
  clock: { now: () => Date.now() },
  env: { get: (name) => process.env[name] },
  writeLog: async (file, text) => {
    await fs.mkdir(path.dirname(file), { recursive: true });
    await Bun.write(file, text);
  },
  log: (line) => console.log(line),
  error: (line) => console.error(line),
});

/** Why a run ended with no exit code: the time bound, or else the signal that ended it. */
const stopOf = (r: ProcessResult): Stop | null => {
  if (r.timedOut) return { kind: "timeout", afterMs: COMMAND_TIMEOUT_MS };
  if (r.signal) return { kind: "signal", name: r.signal };
  return null;
};

/** Run `command` and give its exit code, its output, and why it stopped with no exit code. A program that is missing gives 127 and the error text. */
const execute = async (
  command: string,
  cwd: string,
  deps: Deps,
): Promise<{ exitCode: number | null; output: string; stop: Stop | null }> => {
  const argv = plainArgv(command) ?? shellArgv(command);
  try {
    const r = await deps.runner.run(argv.file, argv.args, {
      cwd,
      timeout: COMMAND_TIMEOUT_MS,
    });
    return {
      exitCode: r.exitCode,
      output: r.stdout + r.stderr,
      stop: stopOf(r),
    };
  } catch (err) {
    return {
      exitCode: 127,
      output: `Cannot run ${argv.file}: ${err instanceof Error ? err.message : String(err)}\n`,
      stop: null,
    };
  }
};

/** Run each command of `commands` in order, write its log file, and give its outcome. A failed command does not stop the later ones. */
export const runChecks = async (
  commands: readonly string[],
  cwd: string,
  deps: Deps,
): Promise<Outcome[]> => {
  const start = new Date(deps.clock.now());
  const runId = crypto.randomUUID().slice(0, RUN_ID_LENGTH);
  const root = path.resolve(deps.env.get("CLAUDE_PROJECT_DIR") || cwd);
  const outcomes: Outcome[] = [];
  for (const [i, command] of commands.entries()) {
    const began = deps.clock.now();
    const { exitCode, output, stop } = await execute(command, cwd, deps);
    const ms = deps.clock.now() - began;
    const logFile = path.posix.join(CHECKS_DIR, logName(start, runId, i + 1));
    await deps.writeLog(
      path.join(root, logFile),
      `$ ${command}\nexit: ${exitCode ?? "killed"}\n\n${output}`,
    );
    outcomes.push({
      command,
      exitCode,
      stop,
      ms,
      failures: exitCode === 0 ? null : failureLines(output),
      shortOutput: exitCode === 0 ? passOutput(output) : null,
      logFile,
    });
  }
  return outcomes;
};

/** Run the CLI with `args` and return the exit status. */
export const main = async (
  args: string[],
  cwd: string = process.cwd(),
  deps: Deps = defaults(),
): Promise<number> => {
  if (args.length === 0 || args.some((a) => a.trim() === "")) {
    deps.error(USAGE);
    return 2;
  }
  const flag = flagArg(args);
  if (flag !== undefined) {
    deps.error(FLAG_ERROR({ flag }));
    return 2;
  }
  const outcomes = await runChecks(args, cwd, deps);
  for (const outcome of outcomes)
    for (const line of renderOutcome(outcome)) deps.log(line);
  deps.log(renderTotal(outcomes));
  return outcomes.every(passed) ? 0 : 1;
};
